 let PROOFMODE='item';
 // Order-progress stepper: 1 Customize, 2 Review, 3 Approve, 4 Checkout.
 function setStep(n){ document.querySelectorAll('#mstepper li').forEach(function(li){
   const s=parseInt(li.dataset.s);
   li.classList.toggle('cur',s===n); li.classList.toggle('done',s<n);
   if(s===n) li.setAttribute('aria-current','step');
   else li.removeAttribute('aria-current'); }); }
 // Client-side upload cap (the server enforces the same limit).
 const MAX_UPLOAD_MB=25;
 // Photos already used in basket items (name|bytes) - powers the gentle
 // duplicate-upload heads-up without ever blocking an intentional reuse.
 let USED_PHOTOS=[], PHOTO_META=null;
 function dupPhotoNote(f){ const k=f.name+'|'+f.size; PHOTO_META=k;
   return USED_PHOTOS.indexOf(k)>=0
     ? "<br>&#8505;&#65039; Heads up: this looks like the <b>same photo</b> used in another basket item - totally fine if intentional."
     : ""; }
 // Proof image = the GARMENT photo (the #mgarment layer behind the transparent
 // canvas) WITH the design composited on top - so the proof shows the whole piece,
 // not just the wording on white. Falls back to the canvas alone for wall art (no
 // garment layer) or a cross-origin mockup that would taint the canvas.
 let _CLEAN=false;   // when true, drawArt omits the editor chrome (frame/handles)
 let _PRINTMODE=false;   // #167: when true, drawArt renders the DESIGN ONLY on a transparent
 //                        canvas (no garment mockup/silhouette/shadow) - a DTG print file
 //                        prints onto the real garment, so it must carry only the artwork.
 // #167 Phase 2b: per-side PRINT FILES. For each designed apparel side, render the DESIGN
 // ONLY (the same canvas + coords the buyer approved) at PRINT resolution (~3000px on the
 // long side, mcanvas ratio preserved) on a transparent background. Front is always
 // included; back/sleeves only when designed (sleeves only on a sleeved garment). Returns
 // {side:pngDataURL} or null. The backend hosts these into extra_files; the router's
 // APPAREL_PRINT_CALIBRATED gate still holds apparel to manual until the owner's test
 // print, so an uncalibrated placement can never auto-print. Never throws.
 function _printFiles(){
   if(!IS_APPAREL) return null;
   const cv=document.getElementById('mcanvas'); if(!cv||!cv.width) return null;
   const prev=APPLACEMENT, ow=cv.width, oh=cv.height, K=3000/Math.max(ow,oh);
   const out={};
   _SNAPPING=true; _CLEAN=true; _PRINTMODE=true;
   try{
     if(IS_APPAREL) SIDES[APPLACEMENT]=_captureSide();      // save the side we're on
     cv.width=Math.round(ow*K); cv.height=Math.round(oh*K); // print resolution
     ['front','back','sleeve-left','sleeve-right'].forEach(function(a){
       if(a!=='front'){
         if((a==='sleeve-left'||a==='sleeve-right') && !_garmentSleeves()) return;
         if(!_sideHas(SIDES[a])) return;                    // only designed extra areas
       }
       setPlacement(a); drawArt();
       try{ var u=cv.toDataURL('image/png'); if(u) out[a]=u; }catch(e){}
     });
   }catch(e){}
   cv.width=ow; cv.height=oh;                                // restore the editor canvas
   _PRINTMODE=false; _CLEAN=false;
   try{ setPlacement(prev); drawArt(); }catch(e){}
   _SNAPPING=false;
   return Object.keys(out).length?out:null;
 }
 function _composedProofURL(){
   const cv=document.getElementById('mcanvas'); if(!cv) return '';
   const mg=document.getElementById('mgarment');
   _SNAPPING=true;                       // internal redraws are a READ, not an edit
   _CLEAN=true; drawArt();               // redraw the design WITHOUT the editor chrome
   let url='';
   if(!mg || mg.style.display==='none' || !mg.complete || !mg.naturalWidth){
     try{ url=cv.toDataURL('image/png'); }catch(e){ url=''; }
   } else {
     const tc=document.createElement('canvas'); tc.width=cv.width; tc.height=cv.height;
     const tx=tc.getContext('2d');
     tx.fillStyle='#ffffff'; tx.fillRect(0,0,tc.width,tc.height);
     // object-fit:contain mapping of the garment image into the canvas box
     const ir=mg.naturalWidth/mg.naturalHeight, cr=tc.width/tc.height;
     let dw,dh; if(ir>cr){ dw=tc.width; dh=dw/ir; } else { dh=tc.height; dw=dh*ir; }
     tx.drawImage(mg,(tc.width-dw)/2,(tc.height-dh)/2,dw,dh);
     tx.drawImage(cv,0,0);               // the design (transparent canvas) on top
     try{ url=tc.toDataURL('image/png'); }
     catch(e){ try{ url=cv.toDataURL('image/png'); }catch(e2){ url=''; } }
   }
   _CLEAN=false; drawArt();              // restore the editor view (chrome back)
   _SNAPPING=false;
   return url;
 }
 // FRONT proof view = the front-facing garment showing the FRONT design AND both
 // designed SLEEVES on the arms (a real shirt shows its sleeves from the front). The
 // BACK is a SEPARATE view with only the back design - there are no sleeves on the
 // back. Each sleeve is overlaid by its OWN bound region so it never covers the chest.
 // maxDim (optional) downscales to a JPEG thumbnail; omitted returns a full-size PNG.
 // This is the SINGLE front-with-sleeves compositor - the live proof, the spin flip, the
 // submitted checkout proof AND the basket thumbnail all go through it, so they can never
 // drift apart (one shows sleeves, another doesn't).
 function _composedFrontURL(maxDim){
   const cv=document.getElementById('mcanvas'); if(!cv) return '';
   if(!IS_APPAREL) return _composedProofURL();
   const mg=document.getElementById('mgarment');
   const prev=APPLACEMENT;
   _SNAPPING=true; _CLEAN=true;
   var W=cv.width, H=cv.height, tw=W, th=H;
   if(maxDim){ var _r=W/H; tw=_r>=1?maxDim:Math.round(maxDim*_r); th=_r>=1?Math.round(maxDim/_r):maxDim; }
   var _sc=tw/W, _scY=th/H;                    // full-canvas coords -> target (scaled) coords
   const tc=document.createElement('canvas'); tc.width=tw; tc.height=th;
   const tx=tc.getContext('2d'); tx.fillStyle='#ffffff'; tx.fillRect(0,0,tw,th);
   // 1) front: the garment photo (if any) behind the front design
   setPlacement('front'); drawArt();
   if(mg && mg.style.display!=='none' && mg.complete && mg.naturalWidth){
     const ir=mg.naturalWidth/mg.naturalHeight, cr=tw/th; let dw,dh;
     if(ir>cr){ dw=tw; dh=dw/ir; } else { dh=th; dw=dh*ir; }
     tx.drawImage(mg,(tw-dw)/2,(th-dh)/2,dw,dh);
   }
   tx.drawImage(cv,0,0,tw,th);                 // front silhouette (if drawn on canvas) + front design
   // 2) overlay each DESIGNED sleeve, copying ONLY its bound region so the chest stays.
   //    Sleeveless garments (tank) never composite a sleeve (#tank, defense-in-depth).
   if(_garmentSleeves()) ['sleeve-left','sleeve-right'].forEach(function(a){
     if(!_sideHas(SIDES[a])) return;
     setPlacement(a); drawArt();
     var b=_apparelBound(W,H), pad=4;
     var sx=Math.max(0,b.x-pad), sy=Math.max(0,b.y-pad);
     var sw=Math.min(W-sx,b.w+2*pad), sh=Math.min(H-sy,b.h+2*pad);
     tx.drawImage(cv, sx,sy,sw,sh, sx*_sc,sy*_scY,sw*_sc,sh*_scY);
   });
   setPlacement(prev);
   _CLEAN=false; drawArt(); _SNAPPING=false;
   var url=''; try{ url=maxDim?tc.toDataURL('image/jpeg',0.78):tc.toDataURL('image/png'); }catch(e){ url=''; }
   return url;
 }
 // A small (~240px) JPEG snapshot of the composed proof, captured at add-to-basket
 // so every basket + confirm row can SHOW the exact design the buyer approves
 // ("exactly as shown"). In-memory only (CART is not persisted) and kept tiny on
 // purpose. Returns '' on any failure (e.g. a cross-origin mockup that taints the
 // canvas) - the row then falls back to text, never blocking checkout.
 function _proofThumb(){
   try{
     // Apparel: the thumbnail must match the approved proof (front + BOTH sleeves), so
     // it goes through the single front-with-sleeves compositor at thumbnail size.
     if(IS_APPAREL){ var _u=_composedFrontURL(240); if(_u) return _u; }
     var cv=document.getElementById('mcanvas'); if(!cv||!cv.width) return '';
     var mg=document.getElementById('mgarment');
     _SNAPPING=true; _CLEAN=true; drawArt();
     var max=240, r=cv.width/cv.height;
     var w=r>=1?max:Math.round(max*r), h=r>=1?Math.round(max/r):max;
     var tc=document.createElement('canvas'); tc.width=w; tc.height=h;
     var tx=tc.getContext('2d'); tx.fillStyle='#ffffff'; tx.fillRect(0,0,w,h);
     if(mg&&mg.style.display!=='none'&&mg.complete&&mg.naturalWidth){
       var ir=mg.naturalWidth/mg.naturalHeight, cr=w/h, dw, dh;
       if(ir>cr){ dw=w; dh=dw/ir; } else { dh=h; dw=dh*ir; }
       tx.drawImage(mg,(w-dw)/2,(h-dh)/2,dw,dh);
     }
     tx.drawImage(cv,0,0,w,h);
     var url=''; try{ url=tc.toDataURL('image/jpeg',0.78); }catch(e){ url=''; }
     _CLEAN=false; drawArt(); _SNAPPING=false;
     return url;
   }catch(e){ try{ _CLEAN=false; drawArt(); _SNAPPING=false; }catch(_e){} return ''; }
 }
 // ── Final preview: rotate the garment front<->back so the buyer reviews BOTH
