   var gid=(typeof APPGID!=='undefined'&&APPGID[CURGARMENT])||'';
   var sm=(typeof APPAREL_SIDE_IMG!=='undefined')?(APPAREL_SIDE_IMG[gid]||APPAREL_SIDE_IMG[gid.replace(/_(value|premium)$/,'')]):null;
